pragma solidity >=0.8.0;
contract Utf8Boundary {
    string public shortAscii;   // 16 chars = 16 UTF-8 bytes (<=31, packed)
    string public wide16;       // 16 chars = 32 UTF-8 bytes (crosses 31-byte bound)
    string public wide17;       // 17 chars = 34 UTF-8 bytes
    event Stored(uint8 tagShort, uint8 tag16, uint8 tag17);

    function storeAll(string memory x, string memory y, string memory z) public {
        shortAscii = x;
        wide16 = y;
        wide17 = z;
        emit Stored(uint8(bytes(x).length), uint8(bytes(y).length), uint8(bytes(z).length));
    }

    function tagShort() public view returns (uint8) {
        return uint8(bytes(shortAscii).length);
    }

    function tag16() public view returns (uint8) {
        return uint8(bytes(wide16).length);
    }

    function tag17() public view returns (uint8) {
        return uint8(bytes(wide17).length);
    }
}
